import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { getCart, clearCart } from '../cart';
import API from '../api';

function Checkout() {
  const [cart, setCart] = useState([]);
  const [guestEmail, setGuestEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const token = localStorage.getItem('token');

  useEffect(() => {
    setCart(getCart());
  }, []);

  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const placeOrder = async (email) => {
    setLoading(true);
    setError('');
    try {
      for (const item of cart) {
        await API.post('/orders/', {
          product_id: item.id,
          quantity: item.quantity,
          guest_email: email || null,
        });
      }
      clearCart();
      navigate('/order-success');
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to place order');
    } finally {
      setLoading(false);
    }
  };

  const handleLoggedInOrder = () => {
    placeOrder(null);
  };

  const handleGuestOrder = (e) => {
    e.preventDefault();
    if (!guestEmail) {
      setError('Please enter your email');
      return;
    }
    placeOrder(guestEmail);
  };

  if (cart.length === 0) {
    return (
      <div style={styles.container}>
        <div style={styles.body}>
          <p>Your cart is empty. <Link to="/products">Go shopping</Link></p>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <div style={styles.navbar}>
        <h2 style={styles.logo}>🛒 Ecommerce</h2>
        <Link to="/cart" style={styles.navLink}>← Back to Cart</Link>
      </div>

      <div style={styles.body}>
        <h3 style={styles.heading}>Checkout</h3>

        {/* Order Summary */}
        <div style={styles.summary}>
          <h4 style={styles.sectionTitle}>Order Summary</h4>
          {cart.map(item => (
            <div key={item.id} style={styles.summaryRow}>
              <span>{item.name} x {item.quantity}</span>
              <span>${(item.price * item.quantity).toFixed(2)}</span>
            </div>
          ))}
          <div style={styles.totalRow}>
            <strong>Total</strong>
            <strong>${total.toFixed(2)}</strong>
          </div>
        </div>

        {error && <p style={styles.error}>{error}</p>}

        {/* Logged in */}
        {token ? (
          <div style={styles.section}>
            <h4 style={styles.sectionTitle}>You are logged in</h4>
            <p style={styles.subText}>Your order will be saved to your account.</p>
            <button
              style={styles.primaryBtn}
              onClick={handleLoggedInOrder}
              disabled={loading}
            >
              {loading ? 'Placing Order...' : 'Place Order'}
            </button>
          </div>
        ) : (
          <>
            {/* Sign in option */}
            <div style={styles.section}>
              <h4 style={styles.sectionTitle}>Sign in to your account</h4>
              <p style={styles.subText}>Save your order history and track orders easily.</p>
              <Link to="/login" style={styles.primaryBtn}>Sign In</Link>
            </div>

            <div style={styles.divider}>— OR —</div>

            {/* Guest option */}
            <div style={styles.section}>
              <h4 style={styles.sectionTitle}>Continue as Guest</h4>
              <p style={styles.subText}>Enter your email to receive order confirmation.</p>
              <form onSubmit={handleGuestOrder}>
                <input
                  style={styles.input}
                  type="email"
                  placeholder="Enter your email"
                  value={guestEmail}
                  onChange={(e) => setGuestEmail(e.target.value)}
                  required
                />
                <button style={styles.guestBtn} type="submit" disabled={loading}>
                  {loading ? 'Placing Order...' : 'Continue as Guest'}
                </button>
              </form>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: '#f0f2f5' },
  navbar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#fff', padding: '15px 30px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' },
  logo: { margin: 0 },
  navLink: { color: '#2196F3', textDecoration: 'none', fontWeight: 'bold' },
  body: { padding: '30px', maxWidth: '600px', margin: '0 auto' },
  heading: { marginBottom: '20px', fontSize: '22px' },
  summary: { background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)', marginBottom: '20px' },
  summaryRow: { display: 'flex', justifyContent: 'space-between', padding: '8px 0', borderBottom: '1px solid #f0f0f0', color: '#555' },
  totalRow: { display: 'flex', justifyContent: 'space-between', paddingTop: '12px', fontSize: '18px' },
  section: { background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)', marginBottom: '15px' },
  sectionTitle: { margin: '0 0 8px', fontSize: '16px' },
  subText: { color: '#666', fontSize: '14px', marginBottom: '15px' },
  input: { width: '100%', padding: '10px', borderRadius: '5px', border: '1px solid #ccc', boxSizing: 'border-box', marginBottom: '10px' },
  primaryBtn: { display: 'block', width: '100%', padding: '12px', background: '#2196F3', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '15px', textAlign: 'center', textDecoration: 'none' },
  guestBtn: { width: '100%', padding: '12px', background: '#4CAF50', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '15px' },
  divider: { textAlign: 'center', color: '#999', margin: '10px 0', fontWeight: 'bold' },
  error: { color: 'red', marginBottom: '10px' },
};

export default Checkout;
